SELECT PNO, SOURCE_ID, TITLE, CONTENT, CATEGORY, REGION, TARGET_AGE, START_DATE, END_DATE, APPLY_START_DATE, APPLY_END_DATE, REG_DATE FROM POLICY
AND (
TITLE LIKE '%' || #{keyword} || '%' CONTENT LIKE '%' || #{keyword} || '%' 1=0
)
AND REGION LIKE '%' || #{region} || '%'
AND (APPLY_END_DATE >= TRUNC(SYSDATE) OR APPLY_END_DATE IS NULL)
AND START_DATE >= #{from}
AND START_DATE <= #{to}
ORDER BY REG_DATE DESC OFFSET #{skip} ROWS FETCH NEXT #{size} ROWS ONLY

SELECT COUNT(*) FROM POLICY
AND (
TITLE LIKE '%' || #{keyword} || '%' CONTENT LIKE '%' || #{keyword} || '%' 1=0
)
AND REGION LIKE '%' || #{region} || '%'
AND (APPLY_END_DATE >= TRUNC(SYSDATE) OR APPLY_END_DATE IS NULL)
AND START_DATE >= #{from}
AND START_DATE <= #{to}
